func orangesRotting(grid [][]int) int {
	//	 边界检查
	//
	type pair struct {
		r, c int
	}
	var (
		rChange = []int{0, 0, -1, 1}
		cChange = []int{1, -1, 0, 0}
		step    = make([][]int, len(grid))
		cnt     = 0
		ans     = 0
		que     = []pair{}
	)
	for i := 0; i < len(step); i++ {
		step[i] = make([]int, len(grid[0]))
	}
	for i, v1 := range grid {
		for j, _ := range v1 {
			if grid[i][j] == 2 {
				que = append(que, pair{i, j})
				step[i][j] = 0
			} else if grid[i][j] == 1 {
				cnt++
			}
		}
	}
	if cnt==0{
		return 0
	}
	for len(que) != 0 {
		now := que[0]
		que = que[1:]
		for i := 0; i < 4; i++ {
			nr := now.r + rChange[i]
			nc := now.c + cChange[i]
			if nr >= 0 && nr < len(grid) && nc >= 0 && nc < len(grid[0]) && grid[nr][nc] == 1 {
				step[nr][nc] = step[now.r][now.c] + 1 //
				que = append(que, pair{
					r: nr,
					c: nc,
				})
				grid[nr][nc] = 2
				ans = step[nr][nc]
				cnt--
				if cnt == 0 {
					return ans
				}
			}
		}

	}
	return -1


}
func main() {
	arr := [][]int{{2, 1, 1}, {1, 1, 0}, {0, 1, 1}}
	fmt.Println(orangesRotting(arr))
}

